"""Offline, deterministic checks. These do not validate investment judgments."""
from datetime import datetime
import hashlib
import json
from pathlib import Path
import re

from jsonschema import Draft202012Validator, FormatChecker
from referencing import Registry


class ValidationError(ValueError):
    pass


def require(condition, message):
    if not condition:
        raise ValidationError(message)


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def json_bytes(value):
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2,
                       allow_nan=False) + '\n').encode('utf-8')


def parse_json(raw):
    def pairs(items):
        result = {}
        for key, value in items:
            require(key not in result, 'Duplicate JSON key: ' + key)
            result[key] = value
        return result

    def constant(value):
        raise ValidationError('Non-finite JSON number: ' + value)

    try:
        return json.loads(raw, object_pairs_hook=pairs, parse_constant=constant)
    except (ValueError, UnicodeError) as exc:
        raise ValidationError('Invalid JSON: ' + str(exc)) from exc


def timestamp(value):
    require(isinstance(value, str), 'Timestamp must be a string')
    try:
        result = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError as exc:
        raise ValidationError('Invalid timestamp: ' + value) from exc
    require(result.tzinfo is not None, 'Timestamp must have an explicit timezone')
    return result


def validate_schema(value, schema):
    # The empty registry never fetches remote references. All current contracts
    # are self-contained; adding references requires an explicit local registry.
    Draft202012Validator.check_schema(schema)
    checker = FormatChecker()

    @checker.checks('date-time', raises=(ValueError, TypeError))
    def date_time(value):
        if not isinstance(value, str):
            return True
        require(re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d)', value),
                'Invalid RFC3339 timestamp')
        timestamp(value)
        return True

    validator = Draft202012Validator(schema, format_checker=checker, registry=Registry())
    errors = list(validator.iter_errors(value))
    if errors:
        error = errors[0]
        raise ValidationError('/' + '/'.join(map(str, error.absolute_path)) + ': ' + error.message)


def unique(rows, key):
    values = [row[key] for row in rows]
    require(len(values) == len(set(values)), 'Duplicate ' + key)
    return {row[key]: row for row in rows}


IDENTITY_FIELDS = ('run_id', 'information_cutoff_utc', 'started_at_utc', 'registry_commit',
                   'registry_version', 'data_versions', 'archive_mode', 'archive_repository')
DOMAINS = {'global': 10, 'commodities': 11}


def check_identity(value, identity):
    for key in IDENTITY_FIELDS:
        require(value[key] == identity[key], 'Identity mismatch: ' + key)


def check_facts(facts, cutoff, item_schema):
    result = unique(facts, 'fact_id')
    for fact in facts:
        validate_schema(fact, item_schema)
        if fact['known_at'] is not None:
            require(timestamp(fact['known_at']) <= timestamp(cutoff), 'Fact known after cutoff: ' + fact['fact_id'])
    return result


def validate_coverage(value, required_scopes):
    require(isinstance(value, dict), 'Coverage must be an object')
    require(set(value) == {'expected', 'rows', 'universe_source', 'limitations'}, 'Invalid coverage envelope')
    expected = value['expected']
    require(isinstance(expected, list) and all(isinstance(x, str) and x for x in expected), 'Invalid expected scopes')
    require(len(expected) == len(set(expected)), 'Duplicate expected scope')
    require(set(required_scopes) <= set(expected), 'Coverage omits required baseline scopes')
    require(isinstance(value['universe_source'], str) and value['universe_source'].strip(), 'Missing universe source')
    require(isinstance(value['limitations'], list), 'Coverage limitations must be a list')
    rows = unique(value['rows'], 'scope')
    require(set(rows) == set(expected), 'Coverage rows must match declared universe exactly')
    for row in rows.values():
        require(row.get('status') in ('analyzed', 'data_missing', 'not_applicable'), 'Invalid coverage status')
        require(isinstance(row.get('analysis'), str) and row['analysis'].strip(), 'Coverage needs analysis or a reason')
        require(isinstance(row.get('limitations'), list), 'Missing coverage limitations')
        if row['status'] != 'analyzed':
            require(row['limitations'], 'Missing/unavailable scope needs an explicit limitation')
    return {'expected': len(expected), **{s: sum(r['status'] == s for r in rows.values())
            for s in ('analyzed', 'data_missing', 'not_applicable')}}


def validate_report(report, identity, schema, coverage_scopes=None):
    validate_schema(report, schema)
    check_identity(report, identity)
    domain = report['domain']
    require(domain in DOMAINS, 'Unknown domain')
    require(report['prompt_sha256'] == identity['prompt_sha256'][domain + '_radar'], 'Prompt hash mismatch')
    require(timestamp(report['generated_at_utc']) >= timestamp(identity['started_at_utc']), 'Report predates run')
    require(report['research_status'] == 'complete', 'Only a complete domain report can be frozen')
    numbers = [s['number'] for s in report['sections']]
    require(numbers == list(range(1, DOMAINS[domain] + 1)), 'Section numbers must be complete, unique and ordered')
    require(all(s['title'].strip() and s['markdown'].strip() for s in report['sections']), 'Empty section')
    facts = check_facts(report['facts'], identity['information_cutoff_utc'], schema['properties']['facts']['items'])
    unique(report['coverage'], 'scope')
    unique(report['candidates'], 'idea_id')
    unique(report['idea_ledger'], 'idea_id')
    for item in report['candidates'] + report['delta']:
        require(set(item['fact_ids']) <= set(facts), 'Dangling fact reference: ' + item['idea_id'])
    section_text = '\n'.join(s['markdown'] for s in report['sections'])
    for item in report['candidates']:
        require(item['conditions_markdown'] in section_text, 'Candidate conditions absent from full Markdown: ' + item['idea_id'])
    require(report['machine_representation_complete'] or report['limitations'], 'Incomplete machine representation needs limitations')
    from grok_research_gate import check_research
    scopes = coverage_scopes if coverage_scopes is not None else parse_json((Path(__file__).resolve().parents[1] / 'config/recovery_scopes.json').read_bytes())
    check_research(report, scopes[domain])
    return facts


def render_report(report):
    from grok_research_gate import render_research
    return render_research(report)


def check_pair(global_report, commodities_report):
    for key in IDENTITY_FIELDS:
        require(global_report[key] == commodities_report[key], 'Cross-report mismatch: ' + key)
    left = unique(global_report['facts'], 'fact_id')
    right = unique(commodities_report['facts'], 'fact_id')
    for key in left.keys() & right.keys():
        require(left[key] == right[key], 'Conflicting shared fact: ' + key)
    return {'shared_fact_count': len(left.keys() & right.keys()),
            'mechanical_checks': 'passed', 'investment_quality': 'not_verified_by_code'}


def check_archive(identity, reports, read, schemas):
    """Verify bytes supplied by a reader; never equate local bytes with remote I/O."""
    started = timestamp(identity['started_at_utc'])
    from datetime import timezone, timedelta
    day = started.astimezone(timezone(timedelta(hours=8))).strftime('%Y/%m/%d')
    prefix = f"reports/{day}/{identity['run_id']}"
    statuses = {'batch': 'not_verified', 'index': 'not_verified', 'latest': 'not_verified',
                'ci': 'pending_or_unverified', 'errors': []}
    try:
        for name, data in reports.items():
            require(read(prefix + '/' + name) == data, 'Archive report mismatch: ' + name)
        raw = read(prefix + '/run_manifest.json')
        manifest = parse_json(raw)
        validate_schema(manifest, schemas['run_manifest'])
        check_identity(manifest, identity)
        for key in ('actual_executor', 'actual_model', 'supersedes_run_id'):
            require(manifest[key] == identity[key], 'Manifest execution metadata mismatch: ' + key)
        require(manifest['batch_status'] == 'complete', 'Archive manifest is incomplete')
        require(manifest['prompt_sha256'] == identity['prompt_sha256'], 'Manifest prompt mismatch')
        require(timestamp(manifest['completed_at_utc']) >= max(timestamp(parse_json(reports[d + '.json'])['generated_at_utc'])
                    for d in DOMAINS), 'Batch completion predates report')
        for domain in DOMAINS:
            original = parse_json(reports[domain + '.json'])
            require(manifest['reports'][domain]['generated_at_utc'] == original['generated_at_utc'], 'Manifest report time mismatch')
            require(manifest['previous_reports'][domain] == original['previous_report'], 'Manifest predecessor mismatch')
            for kind, ext in [('markdown', 'md'), ('json', 'json')]:
                name = domain + '.' + ext
                require(manifest['reports'][domain][kind] == {'path': prefix + '/' + name, 'sha256': sha256(reports[name])},
                        'Manifest file identity mismatch: ' + name)
        statuses['batch'] = 'verified'
        index = parse_json(read('manifests/runs.json'))
        validate_schema(index, schemas['runs'])
        require(index['archive_mode'] == identity['archive_mode'], 'Index archive mode mismatch')
        require(index['archive_repository'] == identity['archive_repository'], 'Index repository mismatch')
        rows = unique(index['runs'], 'run_id')
        require(identity['run_id'] in rows, 'Batch absent from success index')
        entry = rows[identity['run_id']]
        for key in ('information_cutoff_utc', 'started_at_utc', 'completed_at_utc'):
            require(entry[key] == manifest[key], 'Index identity mismatch: ' + key)
        require(entry['manifest'] == {'path': prefix + '/run_manifest.json', 'sha256': sha256(raw)}, 'Index manifest hash mismatch')
        statuses['index'] = 'verified'
        latest = parse_json(read('latest/run.json'))
        validate_schema(latest, schemas['latest'])
        require(latest['run_id'] == identity['run_id'], 'Latest points to another batch; assess ordering separately')
        for key in ('information_cutoff_utc', 'started_at_utc', 'archive_mode', 'archive_repository'):
            require(latest[key] == identity[key], 'Latest identity mismatch: ' + key)
        require(latest['manifest'] == entry['manifest'], 'Latest manifest mismatch')
        for domain in DOMAINS:
            for kind, ext in [('markdown', 'md'), ('json', 'json')]:
                name = domain + '.' + ext
                require(latest['reports'][domain][kind] == {'path': 'latest/' + name, 'sha256': sha256(reports[name])},
                        'Latest pointer mismatch: ' + name)
                require(read('latest/' + name) == reports[name], 'Latest mixed or corrupted: ' + name)
        statuses['latest'] = 'verified'
    except (ValueError, OSError, KeyError) as exc:
        statuses['errors'].append(str(exc))
    return statuses
